#include <iostream>
#include <vector>
#include <algorithm>
#include <cassert>
#include <chrono>
#include <ext/pb_ds/assoc_container.hpp>
using namespace std;
using namespace __gnu_pbds;

auto generate_random_address = [] { char *p = new char; delete p; return (uint64_t) p; };

struct hash_function {
    static uint64_t splitmix64(uint64_t x) {
        x += 0x9e3779b97f4a7c15;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;
        x = (x ^ (x >> 27)) * 0x94d049bb133111eb;
        return x ^ (x >> 31);
    }

    uint64_t operator()(uint64_t x) const {
        static const uint64_t seed = splitmix64(chrono::steady_clock::now().time_since_epoch().count() * (generate_random_address() | 1));
        return splitmix64(x ^ seed);
    }
};

const int MODULUS = 1e9 + 7;

struct modNumber {
    int value;

    modNumber(long long v = 0) {
        if (v < 0) v %= MODULUS, v += MODULUS;
        if (v >= MODULUS) v %= MODULUS;
        value = v;
    }

    static int extended_gcd(int a, int m, int &x, int &y) {
        if (m == 0) {
            x = 1; y = 0;
            return a;
        }
        int g = extended_gcd(m, a % m, y, x);
        y -= (a / m) * x;
        return g;
    }

    static int modular_inverse(int a, int m = MODULUS) {
        int x, y;
        extended_gcd(a, m, x, y);
        return (x % m + m) % m;
    }

    explicit operator int() const { return value; }

    modNumber& operator+=(const modNumber &other) {
        value += other.value;
        if (value >= MODULUS) value -= MODULUS;
        return *this;
    }

    modNumber& operator-=(const modNumber &other) {
        value -= other.value;
        if (value < 0) value += MODULUS;
        return *this;
    }

    static unsigned fast_mod(uint64_t x, unsigned m = MODULUS) {
#if !defined(_WIN32) || defined(_WIN64)
        return x % m;
#endif
        unsigned high = x >> 32, low = (unsigned) x;
        unsigned q, r;
        asm("divl %4\n"
            : "=a" (q), "=d" (r)
            : "d" (high), "a" (low), "r" (m));
        return r;
    }

    modNumber& operator*=(const modNumber &other) {
        value = fast_mod((uint64_t) value * other.value);
        return *this;
    }

    modNumber& operator/=(const modNumber &other) {
        return *this *= modNumber::inverse(other.value);
    }

    friend modNumber operator+(const modNumber &a, const modNumber &b) { return modNumber(a) += b; }
    friend modNumber operator-(const modNumber &a, const modNumber &b) { return modNumber(a) -= b; }
    friend modNumber operator*(const modNumber &a, const modNumber &b) { return modNumber(a) *= b; }
    friend modNumber operator/(const modNumber &a, const modNumber &b) { return modNumber(a) /= b; }

    modNumber& operator++() {
        value = (value == MODULUS - 1) ? 0 : value + 1;
        return *this;
    }

    modNumber& operator--() {
        value = (value == 0) ? MODULUS - 1 : value - 1;
        return *this;
    }

    modNumber operator++(int) { modNumber tmp = *this; ++(*this); return tmp; }
    modNumber operator--(int) { modNumber tmp = *this; --(*this); return tmp; }

    modNumber operator-() const {
        return value == 0 ? 0 : MODULUS - value;
    }

    bool operator==(const modNumber &other) const { return value == other.value; }
    bool operator!=(const modNumber &other) const { return value != other.value; }

    static modNumber inverse(int a) {
        return modNumber(modNumber::mod_inv(a));
    }

    modNumber pow(long long p) const {
        assert(p >= 0);
        modNumber base = *this, result = 1;
        while (p > 0) {
            if (p & 1) result *= base;
            base *= base;
            p >>= 1;
        }
        return result;
    }
};

const int MAX_NODES = 10;
int total_N;
modular probability_matrix[MAX_NODES][MAX_NODES];

int main() {
    cin >> total_N;
    for (int i = 0; i < total_N; ++i)
        for (int j = 0; j < total_N; ++j) {
            int p;
            cin >> p;
            probability_matrix[i][j] = modular(p) / modular(100);
        }

    vector<vector<int>> masks_by_count(total_N + 1);
    vector<int> index_lookup(1 << total_N, -1);
    for (int m = 0; m < (1 << total_N); ++m) {
        int c = __builtin_popcount(m);
        index_lookup[m] = masks_by_count[c].size();
        masks_by_count[c].push_back(m);
    }

    gp_hash_table<long long, modular, hash_function> possible_states;
    possible_states[1LL << index_lookup[0]] = 1;

    for (int left_part = 0; left_part < total_N; ++left_part) {
        gp_hash_table<long long, modular, hash_function> new_states;
        vector<modular> product_mask(1 << total_N, 1);
        for (int mask_curr = 0; mask_curr < (1 << total_N); ++mask_curr) {
            for (int r = 0; r < total_N; ++r) {
                product_mask[mask_curr] *= (mask_curr >> r & 1) ? probability_matrix[left_part][r] : modular(1) - probability_matrix[left_part][r];
            }
        }
        vector<long long> new_bits(total_N, 0);
        vector<modular> new_possible_mask(1 << total_N, 0);
        for (auto &state : possible_states) {
            long long current_mask = state.first;
            modular prob_value = state.second;
            fill(new_bits.begin(), new_bits.end(), 0);
            for (int m : masks_by_count[left_part]) {
                if (current_mask >> index_lookup[m] & 1) {
                    for (int i = 0; i < total_N; ++i) {
                        if ((m >> i & 1) == 0) {
                            new_bits[i] |= 1LL << index_lookup[m | 1 << i];
                        }
                    }
                }
            }
            fill(new_possible_mask.begin(), new_possible_mask.end(), 0);
            for (int curr_mask = 1; curr_mask < (1 << total_N); ++curr_mask) {
                new_possible_mask[curr_mask] = new_possible_mask[curr_mask & (curr_mask - 1)] | new_bits[__builtin_ctz(curr_mask)];
                new_states[new_possible_mask[curr_mask]] += prob_value * product_mask[curr_mask];
            }
        }
        possible_states = move(new_states);
    }

    modular total_answer = 0;
    for (auto &state : possible_states) {
        if (state.first >> index_lookup[(1 << total_N) - 1] & 1)
            total_answer += state.second;
    }
    cout << (int)total_answer << '\n';
}
